    private static function filterItemsByPermission(array $items)
    {
        $filteredItems = [];

        foreach ($items as $item) {
            // Step A: If the item requires a permission and the user lacks it, skip it entirely.
            if (isset($item['permission']) && auth()->check() && !auth()->user()->can($item['permission'])) {
                continue;
            }

            // Step B: If the item has dropdown sub-items, filter those recursively too.
            if (isset($item['subItems'])) {
                $item['subItems'] = self::filterItemsByPermission($item['subItems']);

                // Step C: If ALL sub-items were hidden because of permissions, hide the parent category too so we don't have empty dropdowns!
                if (empty($item['subItems'])) {
                    continue;
                }
            }

            $filteredItems[] = $item;
        }

        return $filteredItems;
    }

