    public static function isActive($path)
    {
        $trimmedPath = ltrim($path, '/');
        $currentPath = request()->path(); // Gets the actual current URL (e.g., 'admin-dashboard/activities/create')

        // 1. Exact match (perfect for standard clicks and the main Dashboard)
        if ($currentPath === $trimmedPath) {
            return true;
        }

        // 2. Prevent the root Dashboard from incorrectly highlighting on every single page
        if ($trimmedPath === 'admin-dashboard' || $trimmedPath === '') {
            return false;
        }

        // 3. Prevent overlap between "Schools Submissions" and "Global Submissions"
        // (Because they share the same base URL structure)
        if ($trimmedPath === 'admin-dashboard/activity-submissions' && str_starts_with($currentPath, 'admin-dashboard/activity-submissions/global')) {
            return false;
        }

        // 4. Wildcard Match for Child Routes (create, edit, show, etc.)
        // If current URL is "admin-dashboard/activities/create", it starts with "admin-dashboard/activities/" - returning TRUE!
        return str_starts_with($currentPath, $trimmedPath . '/');
    }

